INSERT INTO `biblio` (`biblio_id`, `unique_id`, `gmd_id`, `item_type_id`, `title`, `sor`, `edition`, `student_id`, `cp_email`, `departement`, `code_ministry`, `isbn_issn`, `publisher_name`, `publish_place`, `publisher_id`, `publish_year`, `collation`, `series_title`, `call_number`, `authors_text`, `supervisors_text`, `examiners_text`, `subjects_text`, `language_id`, `copyright_id`, `license_id`, `source`, `publish_place_id`, `classification`, `notes`, `notes_en`, `image`, `file_att`, `url_crossref`, `opac_hide`, `approval_status`, `integrity_similarity`, `integrity_ai_risk`, `integrity_last_scan`, `submission_id`, `promoted`, `labels`, `frequency_id`, `spec_detail_info`, `input_date`, `last_update`, `uid`, `step`, `hits`) VALUES
(11, 0, 0, 5, 'PENGARUH KEPEMIMPINAN RESONAN, KONSEP DIRI, DAN KESADARAN BERORGANISASI TERHADAP KETERLIBATAN KERJA MELALUI BUDAYA ETNIK PADA PEGAWAI NEGERI SIPIL PEMERINTAH KOTA PANGKALPINANG', NULL, 'Published', '01023621722004', NULL, 'Doktor Ilmu Manajemen', '', NULL, NULL, NULL, NULL, '2021', '102 hal', NULL, '', NULL, NULL, NULL, NULL, 'id', 2, 1, NULL, 1, '', 'Penelitian ini mengusulkan sebuah konsep baru untuk meningkatkan keterlibatan kerja pegawai negeri sipil (PNS) yakni dengan mengambil peran budaya etnik. Penelitian ini juga menganalisis pengaruh kepemimpinan resonan, konsep diri, dan kesadaran berorganisasi secara langsung terhadap budaya etnik, maupun tidak langsung melalui mediasi budaya etnik terhadap keterlibatan kerja. Populasi dalam penelitian ini adalah 3.149 PNS Kota Pangkalpinang Provinsi Kepulauan Bangka Belitung, Indonesia. Sampel responden yang dipilih sebanyak 344 dengan menggunkan propotional random sampling. Alat analisis yang digunakan sebagai alat bantu dalam pengolahan data di dalam penelitian ini adalah Structural Equation Modeling dengan program AMOS versi 22. Hasil penelitian menunjukan bahwa budaya etnik berperan penting dalam memediasi hubungan antara kepemimpinan resonan, konsep diri dan kesadaran berorganisasi terhadap keterlibatan kerja. Budaya etnik pada penelitian ini memiliki dua dimensi dan sebagai variabel intervening, dimensi nggangung menghasilkan kriteria sangat baik dan berpengaruh sedangkan dimensi dak kawa nyusah menghasilkan kriteria cukup dan tidak berpengaruh terhadap keterlibatan kerja. Keterlibatan kerja penting dilakukan PNS karena keterlibatan kerja sebagai keadaan pikiran yang positif, pada pekerjaan yang ditandai dengan semangat, dedikasi, dan penyerapan. Konsep budaya etnik nggangung dan dak kawa nyusah dalam penelitian ini belum pernah diteliti oleh peneliti lain.', '', 'cover_1-20261004171933-0.png', NULL, '', 1, 'pending', 100.00, 2.40, '2026-10-06 08:23:30', 7, 0, NULL, 0, 'dder', '2026-10-04 13:58:28', '2026-10-04 17:19:33', 1, 1, 0),
(14, 0, 47, NULL, 'Pengaruh Kepemimpinan Resonan, Konsep Diri, dan Kesadaran Berorganisasi terhadap Keterlibatan Kerja melalui Budaya Etnik pada Pegawai Negeri Sipil Pemerintah Kota Pangkalpinang', NULL, NULL, '01023621722004', '', 'Doktor Ilmu Manajemen', NULL, NULL, 'Universitas Sriwijaya', 'Palembang', NULL, '2021', '135 hal', NULL, '658.3 AKL p', 'Maulan Aklil', 'Prof. Badia Perizade, M.B.A., Ph.D.|||Dr. Agustina Hanafi, M.B.A.|||Drs H. Bambang Bemby S., M.A., Ph.D.', 'Prof. Dr. Taufiq Marwa, M.Si.|||Dr. Zunaidah, M.Si.|||Marlina Widiyanti Ph.D.', 'Kepemimpinan Resonan|||Konsep Diri|||Kesadaran Berorganisasi|||Keterlibatan Kerja|||Budaya Etnik|||Manajemen Sumber Daya Manusia', 'id', NULL, 0, NULL, NULL, '658.3', 'Puji syukur penulis panjatkan ke hadirat Allah Subhanahu wa ta\'ala karena berkat rahmat dan hidayah-Nya sehingga penulisan disertasi ini dapat diselesaikan sebagaimana mestinya. Penelitian dalam disertasi ini berjudul Pengaruh Kepemimpinan Resonan, Konsep Diri, dan Kesadaran Berorganisasi terhadap Keterlibatan Kerja melalui Budaya Etnik pada Pegawai Negeri Sipil Pemerintah Kota Pangkalpinang sebagai persyaratan untuk memperoleh gelar Doktor pada Program Studi Doktor Ilmu Manajemen Kekhususan Manajemen Sumber Daya Manusia.', 'The author would like to express his gratitude to the presence of Allah Subhanahu wa Ta\'ala for His grace and guidance so that the writing of this dissertation can be completed as it should be. The research in this dissertation is entitled The Influence of Resonant Leadership, Self-Concept, and Organizational Awareness on Work Engagement through Ethnic Culture in Civil Servants of the Pangkalpinang City Government as requirements for obtaining a Doctoral degree in the Management Science Doctoral Study Program Specializing in Human Resources Management.', NULL, NULL, '', 1, 'draft', NULL, NULL, NULL, NULL, 0, NULL, 0, NULL, '2026-10-06 08:51:54', '2026-10-06 08:51:54', 0, 1, 0);

